def _check_dask(dsk, check_names=True, check_dtypes=True, result=None, scheduler=None):
    import dask.dataframe as dd

    # Import here to avoid circular imports
    try:
        from dask.dataframe.dask_expr._collection import DataFrame as ExprDataFrame
        from dask.dataframe.dask_expr._collection import Series as ExprSeries
        from dask.dataframe.dask_expr._collection import Index as ExprIndex
        from dask.dataframe.dask_expr._collection import Scalar as ExprScalar
        has_expr_collections = True
    except ImportError:
        has_expr_collections = False

    if hasattr(dsk, "__dask_graph__"):
        graph = dsk.__dask_graph__()
        if hasattr(graph, "validate"):
            graph.validate()
        if result is None:
            result = dsk.compute(scheduler=scheduler)

        # Check if it's an Index
        if isinstance(dsk, dd.Index) or (has_expr_collections and isinstance(dsk, ExprIndex)) or is_index_like(dsk._meta):
            assert "Index" in type(result).__name__, type(result)
            # assert type(dsk._meta) == type(result), type(dsk._meta)
            if check_names:
                assert dsk.name == result.name
                assert dsk._meta.name == result.name
                if isinstance(result, pd.MultiIndex):
                    assert result.names == dsk._meta.names
            if check_dtypes:
                assert_dask_dtypes(dsk, result)

        # Check if it's a Series
        elif isinstance(dsk, dd.Series) or (has_expr_collections and isinstance(dsk, ExprSeries)) or is_series_like(dsk._meta):
            assert "Series" in type(result).__name__, type(result)
            assert type(dsk._meta) == type(result), type(dsk._meta)
            if check_names:
                assert dsk.name == result.name, (dsk.name, result.name)
                assert dsk._meta.name == result.name
            if check_dtypes:
                assert_dask_dtypes(dsk, result)
            _check_dask(
                dsk.index,
                check_names=check_names,
                check_dtypes=check_dtypes,
                result=result.index,
            )

        # Check if it's a DataFrame
        elif isinstance(dsk, dd.DataFrame) or (has_expr_collections and isinstance(dsk, ExprDataFrame)) or is_dataframe_like(dsk._meta):
            assert isinstance(result, pd.DataFrame), type(result)
            if check_names:
                assert list(dsk.columns) == list(result.columns)
            if check_dtypes:
                assert_dask_dtypes(dsk, result)
            _check_dask(
                dsk.index,
                check_names=check_names,
                check_dtypes=check_dtypes,
                result=result.index,
            )

        # Check if it's a Scalar
        elif isinstance(dsk, dd.core.Scalar) or (has_expr_collections and isinstance(dsk, ExprScalar)):
            assert np.isscalar(result) or isinstance(
                result, (pd.Timestamp, pd.Timedelta)
            )
        else:
            msg = f"Unsupported dask instance {type(dsk)} found"
            raise AssertionError(msg)
        return result
    return dsk
